"use strict";

function Polyglot(options) {
    options = options || {};
    this.phrases = {};
    this.extend(options.phrases || {});
    this.currentLocale = options.locale || "en";
    this.allowMissing = !!options.allowMissing;
    this.warn = options.warn || warn;
}

function flattenPluralMap(map) {
    var key;
    var value;
    var index;
    var result = {};
    for (key in map) {
        if (map.hasOwnProperty(key)) {
            value = map[key];
            for (index in value) {
                result[value[index]] = key;
            }
        }
    }
    return result;
}

function trim(text) {
    return text.replace(/^\s+|\s+$/g, "");
}

function choosePlural(phrase, locale, smartCount) {
    var parts;
    if (null != smartCount && phrase) {
        parts = phrase.split("||||");
        return trim(parts[pluralIndex(locale, smartCount)] || parts[0]);
    }
    return phrase;
}

function pluralType(locale) {
    var types = flattenPluralMap(pluralLocales);
    return types[locale] || types.en;
}

function pluralIndex(locale, count) {
    return pluralRules[pluralType(locale)](count);
}

function interpolate(phrase, options) {
    var key;
    for (key in options) {
        if ("_" !== key && options.hasOwnProperty(key)) {
            phrase = phrase.replace(new RegExp("%\\{" + key + "\\}", "g"), options[key]);
        }
    }
    return phrase;
}

function warn(message) {
    if (typeof console !== "undefined" && console.warn) {
        console.warn("WARNING: " + message);
    }
}

function clone(source) {
    var key;
    var copy = {};
    for (key in source) {
        copy[key] = source[key];
    }
    return copy;
}

Polyglot.VERSION = "0.4.3";

Polyglot.prototype.locale = function (locale) {
    if (locale) {
        this.currentLocale = locale;
    }
    return this.currentLocale;
};

Polyglot.prototype.extend = function (phrases, prefix) {
    var value;
    var key;
    for (key in phrases) {
        if (phrases.hasOwnProperty(key)) {
            value = phrases[key];
            if (prefix) {
                key = prefix + "." + key;
            }
            if ("object" == typeof value) {
                this.extend(value, key);
            } else {
                this.phrases[key] = value;
            }
        }
    }
};

Polyglot.prototype.clear = function () {
    this.phrases = {};
};

Polyglot.prototype.replace = function (phrases) {
    this.clear();
    this.extend(phrases);
};

Polyglot.prototype.t = function (key, options) {
    var phrase;
    var result;
    options = null == options ? {} : options;
    if ("number" == typeof options) {
        options = {
            smart_count: options
        };
    }
    if ("string" == typeof this.phrases[key]) {
        phrase = this.phrases[key];
    } else if ("string" == typeof options._) {
        phrase = options._;
    } else if (this.allowMissing) {
        phrase = key;
    } else {
        this.warn('Missing translation for key: "' + key + '"');
        result = key;
    }
    if ("string" == typeof phrase) {
        options = clone(options);
        result = interpolate(choosePlural(phrase, this.currentLocale, options.smart_count), options);
    }
    return result;
};

Polyglot.prototype.has = function (key) {
    return key in this.phrases;
};

var pluralRules = {
    chinese: function () {
        return 0;
    },
    german: function (count) {
        return 1 !== count ? 1 : 0;
    },
    french: function (count) {
        return count > 1 ? 1 : 0;
    },
    russian: function (count) {
        return count % 10 == 1 && count % 100 != 11 ? 0 : count % 10 >= 2 && count % 10 <= 4 && (count % 100 < 10 || count % 100 >= 20) ? 1 : 2;
    },
    czech: function (count) {
        return 1 === count ? 0 : count >= 2 && count <= 4 ? 1 : 2;
    },
    polish: function (count) {
        return 1 === count ? 0 : count % 10 >= 2 && count % 10 <= 4 && (count % 100 < 10 || count % 100 >= 20) ? 1 : 2;
    },
    icelandic: function (count) {
        return count % 10 != 1 || count % 100 == 11 ? 1 : 0;
    }
};

var pluralLocales = {
    chinese: ["fa", "id", "ja", "ko", "lo", "ms", "th", "tr", "zh"],
    german: ["da", "de", "en", "es", "fi", "el", "he", "hu", "it", "nl", "no", "pt", "sv"],
    french: ["fr", "tl", "pt-br"],
    russian: ["hr", "ru"],
    czech: ["cs"],
    polish: ["pl"],
    icelandic: ["is"]
};

module.exports = Polyglot;
